-- Patient Safety & Quality Improvement: Part 4 (Questions 151-200)
-- US MD / MBBS / USMLE Step 3
-- Target: Supabase (PostgreSQL)
-- Topic Slug: ethics-patient-safety

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-patient-safety' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic slug ethics-patient-safety not found.';
    END IF;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- SURGICAL SAFETY & CHECKLISTS
    (v_topic_id, 'Which of the following is a mandated component of the Universal Protocol for preventing wrong-site surgery?', '["Pre-operative verification", "Site marking", "A surgical \"Time-Out\"", "All of the above"]', 3, 'The Universal Protocol (mandated by TJC) includes verification of the patient/procedure, marking the operative site, and a time-out immediately before incision.'),
    (v_topic_id, 'During the surgical "Time-Out," who on the team is required to participate?', '["Only the surgeon and the anesthesiologist", "Only the nurse", "All members of the surgical team", "The patient''s family"]', 2, 'The Time-Out is a collective responsibility; all team members must pause and actively agree on the patient identity, site, and procedure.'),
    (v_topic_id, 'The "Sign-In" phase of the WHO Surgical Safety Checklist occurs:', '["Before the induction of anesthesia", "Before the surgical incision", "Before the patient leaves the operating room", "In the recovery room (PACU)"]', 0, 'Sign-In involves checking the patient identity, site, procedure, consent, and anesthesia safety (e.g., airway risk).'),
    (v_topic_id, 'The "Time-Out" phase of the WHO Surgical Safety Checklist occurs:', '["Before induction of anesthesia", "Immediately before the skin incision", "After the first stitch is placed", "When the patient is awake"]', 1, 'The Time-Out is the final check performed just before the procedure begins.'),
    (v_topic_id, 'Which of the following is a key task during the "Sign-Out" phase of the surgical checklist?', '["Labeling surgical specimens", "Reviewing anticipated blood loss", "Marking the surgical site", "Checking the anesthesia machine"]', 0, 'Sign-Out includes specimen labeling, sponge/instrument counts, and identifying any equipment problems or post-op concerns.'),

    -- NEVER EVENTS & PROCEDURAL ERRORS
    (v_topic_id, 'Which of the following is considered a "Never Event" in the operating room?', '["A post-operative wound infection", "A retained surgical sponge after closure", "The surgery taking longer than expected", "The surgeon needing to change the plan intraoperatively"]', 1, 'Retained foreign bodies (sponges, instruments) are classic Never Events that are considered evidence of a major breakdown in safety protocols.'),
    (v_topic_id, 'What is the most effective way to prevent a retained foreign body (RFB) during a high-risk case (e.g., emergency laparotomy)?', '["Counting sponges once at the end", "Manual counts + Radiopaque markers on all items + Routine intraoperative X-ray before closure", "Asking the surgeon if they see anything", "Checking the patient''s trash can"]', 1, 'Redundancy (manual counts, markers, and imaging in high-risk scenarios) is essential for preventing RFBs.'),
    (v_topic_id, '"Wrong-Site Surgery" is most commonly caused by a failure in:', '["Surgical skill", "Communication and adherence to standardized protocols", "Hospital billing", "Patient cooperation"]', 1, 'Wrong-site errors are almost always system failures involving miscommunication, incorrect scheduling, or bypassing the time-out process.'),
    (v_topic_id, 'If a surgeon realizes they are about to operate on the wrong side, but is stopped by a resident, this is a:', '["Sentinel event", "Near miss", "No-harm event", "Adverse event"]', 1, 'Because the error was caught before it reached the patient, it is a near miss.'),
    (v_topic_id, 'Which of the following is a "Latent Error" that contributes to wrong-site surgery?', '["The surgeon being tired", "Inconsistent site-marking policies across different departments", "The nurse forgetting to speak up", "The patient pointing to the wrong leg"]', 1, 'A lack of standardized policies is a system-level (latent) flaw.'),

    -- INFECTION CONTROL (BUNDLES & HYGIENE)
    (v_topic_id, 'A "Bundle" in infection control is defined as:', '["A group of unrelated tasks", "A small group of evidence-based interventions that, when performed together, result in better outcomes", "A stack of sterile towels", "A collection of antibiotics"]', 1, 'Bundles (like the CLABSI bundle) rely on the "all-or-nothing" principle—every step must be completed for every patient every time.'),
    (v_topic_id, 'Which of the following is a component of the "Central Line-Associated Bloodstream Infection" (CLABSI) prevention bundle?', '["Hand hygiene", "Maximal sterile barrier precautions (cap, mask, sterile gown, sterile gloves, large sterile drape)", "Chlorhexidine skin antisepsis", "All of the above"]', 3, 'The bundle also includes optimal site selection (avoiding the femoral vein) and daily review of the line''s necessity.'),
    (v_topic_id, 'What is the most effective skin antiseptic for central line insertion to reduce infection risk?', '["70% Alcohol", "Povidone-iodine (Betadine)", "Chlorhexidine gluconate (>0.5% with alcohol)", "Soap and water"]', 2, 'Chlorhexidine has superior persistent antimicrobial activity and is the standard for line insertion.'),
    (v_topic_id, 'Which vein is associated with the HIGHEST risk of infection and should be avoided for central venous catheterization if possible?', '["Internal jugular vein", "Subclavian vein", "Femoral vein", "Basilic vein"]', 2, 'The femoral site has a significantly higher risk of both infection and thrombosis compared to subclavian or jugular sites.'),
    (v_topic_id, 'The most important intervention for preventing "Ventilator-Associated Pneumonia" (VAP) is:', '["Keeping the head of the bed elevated (30-45 degrees)", "Using systemic antibiotics prophylactically", "Changing the ventilator circuit every 24 hours", "Suctioning the patient every 10 minutes"]', 0, 'Elevation of the head of the bed is a key component of the VAP bundle to prevent aspiration of secretions.'),

    -- MORE INFECTION CONTROL
    (v_topic_id, 'Which of the following is the most important single action to prevent the spread of healthcare-associated infections (HAIs)?', '["Wearing a mask at all times", "Hand hygiene (washing or alcohol-based rub)", "Using only sterile equipment", "Regularly mopping the floors"]', 1, 'Hand hygiene remains the cornerstone of infection prevention.'),
    (v_topic_id, '"Contact Precautions" (gown and gloves) are required for patients colonized or infected with which of the following?', '["Methicillin-resistant Staphylococcus aureus (MRSA)", "Clostridioides difficile", "Vancomycin-resistant Enterococcus (VRE)", "All of the above"]', 3, 'These organisms are easily spread via direct or indirect contact with the patient or their environment.'),
    (v_topic_id, 'When caring for a patient with a known "Clostridioides difficile" infection, hand hygiene MUST be performed with:', '["Alcohol-based hand rub", "Soap and water (physical scrubbing)", "Chlorhexidine", "Sterile saline"]', 1, 'Alcohol rub is ineffective against C. diff spores; physical washing with soap and water is required to remove them from hands.'),
    (v_topic_id, 'Which type of room is required for a patient with suspected pulmonary tuberculosis (Airborne Precautions)?', '["Positive-pressure room", "Negative-pressure room with HEPA filtration", "Standard private room with the door open", "Multi-patient ward"]', 1, 'Negative pressure ensures that air flows INTO the room and is then filtered/exhausted safely, preventing the escape of infectious nuclei.'),
    (v_topic_id, 'For which of the following diseases are "Droplet Precautions" (surgical mask) required?', '["Measles", "Influenza", "Varicella (Chickenpox)", "Tuberculosis"]', 1, 'Droplet precautions are used for pathogens spread through large respiratory droplets (e.g., flu, pertussis, meningitis). Measles, Varicella, and TB require Airborne precautions.'),

    -- CATHETER-ASSOCIATED UTI (CAUTI)
    (v_topic_id, 'The single greatest risk factor for developing a healthcare-associated urinary tract infection (UTI) is:', '["Old age", "Prolonged use of an indwelling urinary catheter", "Low fluid intake", "The use of perineal hygiene wipes"]', 1, 'The risk of CAUTI increases significantly with every day the catheter remains in place.'),
    (v_topic_id, 'Which of the following is a recommended strategy to reduce the risk of CAUTI?', '["Routine changing of the catheter every 7 days", "Maintaining a closed drainage system and unobstructed flow", "Prophylactic bladder irrigation with antibiotics", "Using a larger diameter catheter to ensure drainage"]', 1, 'Maintaining a sterile, closed system and removing the catheter as soon as it is no longer indicated are the most effective strategies.'),
    (v_topic_id, 'True or False: Asymptomatic bacteriuria in a catheterized patient should be routinely treated with antibiotics to prevent CAUTI.', '["True", "False"]', 1, 'Treatment of asymptomatic bacteriuria is not recommended (except in pregnancy or before urologic procedures) as it does not prevent UTI and promotes antibiotic resistance.'),
    (v_topic_id, 'Which of the following is a "Forcing Function" or "Hard Stop" that can reduce CAUTI?', '["A nurse-driven protocol for catheter removal based on specific criteria", "An EHR alert that prompts the physician every 24 hours to justify the continued need for the catheter", "A poster about hand hygiene", "Both A and B"]', 3, 'Protocols and digital prompts force clinicians to actively consider if the catheter is still necessary.'),

    -- BLOOD & SPECIMEN SAFETY
    (v_topic_id, 'The most common cause of a hemolytic transfusion reaction is:', '["An unknown rare antibody", "Misidentification of the patient or the blood product", "Failure of the blood bank cooling system", "A mistake in the lab''s cross-matching software"]', 1, 'Clerical errors at the bedside (administering blood to the wrong patient) are the leading cause of transfusion-related deaths.'),
    (v_topic_id, 'To ensure safe blood transfusion, the final verification at the bedside MUST be performed by:', '["One nurse alone", "The physician and the patient", "Two qualified healthcare providers (independent double-check)", "The blood bank technician"]', 2, 'Independent verification by two people is a critical redundancy for high-risk procedures like blood transfusion.'),
    (v_topic_id, 'A laboratory specimen labeled with the wrong patient''s name is a:', '["Sentinel event if the patient dies", "Pre-analytical error", "Near miss if caught before the results are used for treatment", "All of the above"]', 3, 'Specimen labeling errors are common and can lead to major diagnostic and treatment mistakes.'),
    (v_topic_id, 'What is the "Gold Standard" for patient identification before a procedure or medication administration?', '["Asking the patient their room number", "Using two independent identifiers (e.g., Full Name and Date of Birth)", "Checking the patient''s chart", "Recognizing the patient''s face"]', 1, 'Patient room number or physical location should NEVER be used as an identifier.'),

    -- SHARPS SAFETY & OCCUPATIONAL HEALTH
    (v_topic_id, 'The most common mechanism of occupationally acquired HIV or Hepatitis B among healthcare workers is:', '["Splashing of fluid into the eyes", "Percutaneous needle-stick injury", "Contact with intact skin", "Touching contaminated laundry"]', 1, 'Needle-stick injuries remain a major occupational hazard.'),
    (v_topic_id, 'Which of the following is a "Human Factors" intervention to reduce needle-stick injuries?', '["Telling staff to \"be more careful\"", "Implementing safety-engineered devices (e.g., self-sheathing needles)", "Increasing the penalty for needle-sticks", "Banning the use of needles entirely"]', 1, 'Safety-engineered devices use passive or active mechanisms to protect the sharp end after use, reducing reliance on the user''s vigilance.'),
    (v_topic_id, 'Which of the following practices is strongly DISCOURAGED in sharps safety?', '["Disposing of sharps in a puncture-resistant container", "Recapping needles using a two-handed technique", "Using needle-less IV connectors", "Using the \"Neutral Zone\" technique in the OR (not passing sharps hand-to-hand)"]', 1, 'Two-handed recapping is a leading cause of needle-sticks and should never be performed.'),
    (v_topic_id, 'If a healthcare worker suffers a needle-stick injury from a patient with unknown HIV status, when should post-exposure prophylaxis (PEP) be started?', '["Wait for the patient''s test results", "As soon as possible, ideally within hours", "After 24 hours to let the wound heal", "Only if the worker develops symptoms"]', 1, 'PEP is most effective when started as soon as possible after exposure.'),

    -- INFORMED CONSENT & SAFETY
    (v_topic_id, 'Informed consent is a process primarily intended to:', '["Protect the hospital from lawsuits", "Ensure the patient understands the risks, benefits, and alternatives to a procedure", "Speed up the surgical schedule", "Convince the patient to have the surgery"]', 1, 'Consent is about patient autonomy and ensuring they are an active partner in a safe care plan.'),
    (v_topic_id, 'Which of the following patients can legally provide informed consent?', '["A 10-year-old child with a broken arm", "A 40-year-old adult who is currently intoxicated", "A 25-year-old adult with a profound intellectual disability", "A 75-year-old adult with early-stage dementia who is currently oriented and understands the decision"]', 3, 'Capacity is decision-specific; having dementia does not automatically mean a patient lacks capacity for a specific, simpler decision.'),
    (v_topic_id, 'In an emergency situation where a patient is unconscious and no surrogate is available, what is the legal standard for proceeding with life-saving treatment?', '["Wait for a court order", "Proceed under the principle of Implied Consent", "Do nothing until a family member is found", "Ask a second physician to sign the consent form (standard in many hospitals)"]', 1, 'Implied consent assumes a reasonable person would want life-saving treatment in an emergency.'),
    (v_topic_id, 'A patient agrees to a "Knee Surgery" but the surgeon performs an "Ankle Surgery" instead. This is a failure of:', '["Diagnostic skill", "Informed consent and procedural verification (Wrong-site surgery)", "Communication with the family", "Hospital billing"]', 1, 'Informed consent must be specific to the procedure and site being operated on.'),

    -- MISC PROCEDURAL SAFETY
    (v_topic_id, 'Which of the following is a "High-Alert" medication that often requires independent double-checks?', '["Saline flush", "Insulin", "Acetaminophen", "Multivitamin"]', 1, 'High-alert medications (e.g., insulin, anticoagulants, concentrated electrolytes) have a high risk of causing significant harm when used in error.'),
    (v_topic_id, 'The use of "Standard Precautions" means that healthcare workers should:', '["Treat only patients with known infections as infectious", "Treat all patients'' blood and body fluids as potentially infectious", "Wear a gown for every patient encounter", "Only wash hands after touching a patient"]', 1, 'Standard precautions are applied to ALL patients, regardless of suspected or confirmed infection status.'),
    (v_topic_id, 'What is the purpose of "Maximal Sterile Barrier Precautions" during central line insertion?', '["To make the doctor look professional", "To minimize the patient''s skin exposure to air", "To prevent the introduction of microorganisms from the environment or the provider during the procedure", "To speed up the procedure"]', 2, 'Maximal barriers (including gown, mask, and full-body drape) are significantly more effective than "clean" or "limited sterile" techniques.'),
    (v_topic_id, 'A patient develops an infection in their surgical wound 48 hours after an operation. This is classified as a:', '["Natural disease", "Healthcare-Associated Infection (HAI)", "Sentinel event", "Non-preventable adverse event"]', 1, 'HAIs (or nosocomial infections) are those that develop as a result of care in a healthcare facility.'),

    -- MORE SURGICAL SAFETY
    (v_topic_id, 'Which member of the surgical team should typically lead the "Time-Out"?', '["The medical student", "Any designated team member (often the nurse or surgeon)", "The hospital administrator", "The patient"]', 1, 'While anyone can lead, it must be a designated person who ensures that everyone is listening and participating.'),
    (v_topic_id, 'True or False: Site marking should be done with a permanent marker and should be visible after the patient is draped.', '["True", "False"]', 0, 'The mark must survive the surgical prep and be visible during the time-out.'),
    (v_topic_id, 'If there is a disagreement during the time-out about the surgical site, what is the next step?', '["Let the surgeon decide", "Ask the anesthesiologist", "Stop and resolve the discrepancy using primary records (e.g., consent form, imaging) before proceeding", "Flip a coin"]', 2, 'The procedure should not start until the entire team is in 100% agreement.'),
    (v_topic_id, 'Which of the following is a common reason why surgical counts (sponges/needles) fail to prevent a retained item?', '["The count was not performed", "The count was performed and reported as \"correct\" despite a missing item (human error)", "The surgeon was in a hurry", "All of the above"]', 3, 'Counts are a manual process subject to distraction, fatigue, and "confirmation bias" (expecting the count to be correct).'),
    (v_topic_id, 'An "Incident Report" should be filed after which of the following OR events?', '["A retained needle", "A patient fall during transfer", "A failed intubation needing a backup plan", "All of the above"]', 3, 'Any deviation from standard safety or unexpected occurrence should be reported.'),

    -- INFECTION CONTROL REVISITED
    (v_topic_id, 'The "Five Moments for Hand Hygiene" (WHO) include:', '["Before touching a patient", "Before a clean/aseptic procedure", "After body fluid exposure risk", "All of the above"]', 3, 'The other two moments are "After touching a patient" and "After touching patient surroundings."'),
    (v_topic_id, 'Alcohol-based hand rub is generally PREFERRED over soap and water because it:', '["Is more effective at killing most bacteria and viruses", "Is faster and less damaging to skin", "Increases compliance", "All of the above"]', 3, 'Except for C. diff and visibly soiled hands, alcohol rub is the standard.'),
    (v_topic_id, 'Isolation signs on a patient''s door are intended to:', '["Embarrass the patient", "Protect other patients, visitors, and staff from infectious transmission", "Identify the patient''s insurance status", "Make the hallway look colorful"]', 1, 'Isolation is a key structural barrier in infection control.'),
    (v_topic_id, 'The use of "Negative Pressure" in an isolation room prevents air from __________.', '["Entering the room", "Leaving the room and entering the hallway", "Circulating inside the room", "Becoming too cold"]', 1, 'Negative pressure (Airborne Precautions) protects those outside the room.'),
    (v_topic_id, 'In "Standard Precautions," when should gloves be worn?', '["For every patient encounter", "When contact with blood, body fluids, non-intact skin, or mucous membranes is anticipated", "Only for known HIV patients", "Only in the operating room"]', 1, 'Gloves are not needed for routine contact with intact skin (e.g., taking blood pressure).');
END $$;
